<?php
namespace App\Services\Selection; use App\Models\{Player,Squad,SquadPlayer}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class TournamentSquadService { public function __construct(private readonly SelectionAuditService $audit){} public function syncPlayers(Squad $squad,array $ids,int $actor):Squad{if(in_array($squad->status,['Finalized','Locked'],true))throw ValidationException::withMessages(['squad'=>'Finalized or locked squads cannot be modified.']); if(count($ids)>$squad->max_players)throw ValidationException::withMessages(['player_ids'=>"Squad cannot exceed {$squad->max_players} players."]); return DB::transaction(function()use($squad,$ids,$actor){foreach($ids as $id){Player::query()->findOrFail($id); SquadPlayer::query()->updateOrCreate(['squad_id'=>$squad->id,'player_id'=>$id],['status'=>'Selected','added_by'=>$actor,'added_at'=>now(),'removed_at'=>null]);}$squad->players()->whereNotIn('player_id',$ids?:[-1])->update(['status'=>'Withdrawn','removed_at'=>now()]);$this->audit->record('tournament_squad.players_synced',$actor,['squad_id'=>$squad->id,'player_ids'=>$ids]);return $squad->fresh(['players.player']);});} public function finalize(Squad $squad,int $actor):Squad{$n=$squad->players()->whereNull('removed_at')->where('status','!=','Withdrawn')->count();if($n<$squad->min_players||$n>$squad->max_players)throw ValidationException::withMessages(['squad'=>"Squad must contain between {$squad->min_players} and {$squad->max_players} players."]);$squad->update(['status'=>'Finalized']);$this->audit->record('tournament_squad.finalized',$actor,['squad_id'=>$squad->id]);return $squad->fresh(['players.player']);} }
